#include <iostream>
#include <string>
#include <string_view>

class Employee {
public:
    // C++17 inline static member variable
    inline static unsigned int count{0};

    Employee(std::string_view first, std::string_view last)
        : firstName(first), lastName(last) {
        ++count;
        std::cout << "Employee constructor for " << firstName << ' ' << lastName << " called.\n";
    }

    ~Employee() {
        std::cout << "~Employee() called for " << firstName << ' ' << lastName << "\n";
        --count;
    }

    // Static member function: class-wide, no 'this' pointer, cannot be const
    static unsigned int getCount() {
        return count;
    }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }

private:
    std::string firstName;
    std::string lastName;
};

int main() {
    std::cout << "Number of employees before instantiation of any objects is "
              << Employee::getCount() << "\n";

    {
        Employee e1{"Susan", "Baker"};
        Employee e2{"Robert", "Jones"};

        std::cout << "Number of employees after objects are instantiated is "
                  << Employee::getCount() << "\n\n";

        std::cout << "Employee 1: " << e1.getFirstName() << " " << e1.getLastName() << "\n"
                  << "Employee 2: " << e2.getFirstName() << " " << e2.getLastName() << "\n\n";
    }

    std::cout << "\nNumber of employees after objects are deleted is "
              << Employee::getCount() << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <memory>

class ResourceOwner {
public:
    explicit ResourceOwner(int id)
        : identifier{id} {
        std::cout << "Constructing ResourceOwner id=" << identifier << "\n";
    }

    ~ResourceOwner() {
        // Termination housekeeping
        std::cout << "Destructing ResourceOwner id=" << identifier << " (housekeeping done)\n";
    }

    // Access function (read-only / predicate)
    int getId() const { return identifier; }
    bool isValid() const { return validateId(); } // delegates to utility function

private:
    int identifier;

    // Utility function: private helper for internal invariant checking
    bool validateId() const {
        return identifier > 0;
    }
};

int main() {
    std::cout << "Entering outer scope\n";
    ResourceOwner obj1{101};
    ResourceOwner* ptr = &obj1;

    std::cout << "Access via dot operator: id=" << obj1.getId() << "\n";
    std::cout << "Access via arrow operator: valid=" << (ptr->isValid() ? "true" : "false") << "\n";

    {
        std::cout << "Entering inner scope\n";
        ResourceOwner obj2{202};
        std::cout << "Inner object id=" << obj2.getId() << "\n";
        std::cout << "Exiting inner scope\n";
    }

    std::cout << "Exiting outer scope\n";
    return 0;
}
